"use strict";
const capabilityLabels={can_collect_leads:'Raccogliere richieste di contatto',can_request_phone:'Chiedere il telefono',can_request_email:'Chiedere l’email',can_book_appointments:'Prenotare appuntamenti — simulazione locale',can_modify_appointments:'Modificare appuntamenti — predisposizione, azione non disponibile',can_cancel_appointments:'Cancellare appuntamenti — predisposizione, azione non disponibile',can_handoff_to_human:'Trasferire al personale',can_use_whatsapp:'Usare il canale WhatsApp simulato',can_use_voice:'Modalità vocale simulata',can_send_to_crm:'Inviare al CRM simulato'};
async function loadAgent(){const a=await request('agent-settings');for(const [key,label] of Object.entries(capabilityLabels)){const l=node('label'),c=node('input');c.type='checkbox';c.name=key;c.checked=a.capabilities[key];l.append(c,document.createTextNode(label));$('#capabilities').append(l)}for(const [key,value] of Object.entries(a.branding))$('#agent-settings').elements[key].value=value;const f=$('#agent-settings');f.elements.goals.value=a.goals;f.elements.crm_auto.checked=a.crm_auto;f.elements.scoring.value=JSON.stringify(a.scoring,null,2);f.elements.departments.value=JSON.stringify(a.departments,null,2);await agentActivity()}
async function agentActivity(){const d=await request('agent-activity');$('#agent-activity').textContent='Lingue delle conversazioni: '+Object.entries(d.languages).map(([k,v])=>k+': '+v).join(' · ')+'\nPrenotazioni di prova: '+d.bookings.length+'\n'+d.intelligence.map(i=>'Richiesta: '+i.score+'/100 · Esito: '+i.stage+' · '+JSON.parse(i.reasons).map(r=>r.label+' (+'+r.points+')').join(', ')+' · Reparto: '+(JSON.parse(i.department).name||'Da assegnare')).join('\n')+'\nAzioni recenti: '+d.actions.map(a=>a.action+' — '+a.outcome+' — '+date(a.created_at)).join('\n');const sources=await request('source-revisions');$('#source-revisions').replaceChildren();for(const r of sources.revisions){const box=node('article');box.append(node('strong',r.url+' — '+r.status),node('p',r.content));if(r.status==='pending'){const button=node('button','Approva questa versione per l’AI');button.addEventListener('click',async()=>{try{await request('source-approve',{revision:r.id});await agentActivity()}catch(e){$('#agent-status').textContent=e.message}});box.append(button)}$('#source-revisions').append(box)}}
$('#agent-settings').addEventListener('submit',async e=>{e.preventDefault();try{const f=e.target,capabilities={},branding={};for(const key of Object.keys(capabilityLabels))capabilities[key]=f.elements[key].checked;for(const key of ['assistant_name','greeting','color','logo','avatar','tone','contact','widget_position'])branding[key]=f.elements[key].value;await request('agent-settings',{capabilities,branding,goals:f.elements.goals.value,crm_auto:f.elements.crm_auto.checked,scoring:JSON.parse(f.elements.scoring.value),departments:JSON.parse(f.elements.departments.value)});$('#agent-status').textContent='Salvato. Nuove autorizzazioni e branding valgono per nuove chat; i permessi revocati bloccano subito le azioni.'}catch(e){$('#agent-status').textContent=e.message}});
$('#slot-form').addEventListener('submit',async e=>{e.preventDefault();try{const f=new FormData(e.target);await request('local-slot',{starts:new Date(f.get('starts')).toISOString(),label:f.get('label')});$('#agent-status').textContent='Disponibilità di prova aggiunta.';e.target.reset()}catch(e){$('#agent-status').textContent=e.message}});
$('#refresh-agent').addEventListener('click',()=>agentActivity().catch(e=>$('#agent-status').textContent=e.message));
async function human(mode,message=''){if(!selectedConversation)return;try{await request('human',{conversation:selectedConversation,mode,message});$('#human-status').textContent='Conversazione aggiornata.';const data=await request('conversations/'+encodeURIComponent(selectedConversation));showMessages(data.messages)}catch(e){$('#human-status').textContent=e.message}}
for(const b of document.querySelectorAll('[data-mode]'))b.addEventListener('click',()=>human(b.dataset.mode));$('#send-human').addEventListener('click',()=>human('HUMAN_ACTIVE',$('#human-message').value));$('#save-stage').addEventListener('click',async()=>{if(!selectedLead){$('#human-status').textContent='Apri una richiesta dalla scheda Richieste.';return}try{await request('lead-stage',{lead:selectedLead,stage:$('#lead-stage').value});$('#human-status').textContent='Esito aggiornato.'}catch(e){$('#human-status').textContent=e.message}});
loadAgent().catch(e=>$('#agent-status').textContent=e.message);
